        "id": "sprint-8-t49",
        "title": "Currently, there are no guidelines for users taking photos, which may result in pictures being taken",
        "description": "Visual Overlay Guides for In-App Camera",
        "background": "Visual Overlay Guides for In-App Camera",
        "objective": "Currently, there are no guidelines for users taking photos, which may result in pictures being taken under various conditions, not follow to the specified guidance.\nTo improve the quality and reliability of photo submissions during DTE missions in the AYO Toko mobile app, we are introducing key enhancements that address both user experience and submission integrity.\nVisual Overlay Guides for In-App Camera\nUsers often struggle to align their photos with brand-specific display requirements (e.g., Coca-Cola planogram, Aqua Danone layout, cigarette display standards). This leads to frequent submission errors, rework, and delays in mission validation. To address this, we will implement visual overlay guides directly on the in-app camera. These semi-transparent templates will help users align their camera shots with the expected visual standards, reducing human error and ensuring compliance with planogram expectations. This feature enhances clarity and guidance during submission, resulting in higher-quality, brand-compliant data capture.",
        "platform": "DTE",
        "assignee": "Hanif/Jess",
        "priority": "Medium",
        "stage": "todo",
        "progress": 0,
        "mandays": "5",
        "jira": "",
        "dependency": "Add Visual Overlay Guide",
        "statusRaw": "",
        "commentsCount": 1,
